import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"49 - Themes And App Mode","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/49-themes.md","filePath":"developers/design-documentation/49-themes.md"}'),r={name:"developers/design-documentation/49-themes.md"};function s(n,e,c,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="_49-themes-and-app-mode" tabindex="-1">49 - Themes And App Mode <a class="header-anchor" href="#_49-themes-and-app-mode" aria-label="Permalink to &quot;49 - Themes And App Mode&quot;">​</a></h1><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h2><p><code>frontend/src/stores/themeStore.ts</code> is a persisted Zustand store with three related values:</p><table tabindex="0"><thead><tr><th>Value</th><th>Options</th><th>Purpose</th></tr></thead><tbody><tr><td><code>mode</code></td><td><code>light</code>, <code>dark</code></td><td>User preference in live mode</td></tr><tr><td><code>color</code></td><td>zinc, slate, stone, gray, neutral, red, rose, orange, green, blue, yellow, violet</td><td>Accent theme</td></tr><tr><td><code>appMode</code></td><td><code>live</code>, <code>analyzer</code></td><td>Backend trading mode reflected in UI</td></tr></tbody></table><p>The store persists under <code>tradeboard-theme</code>. Rehydration applies the <code>.dark</code> class, <code>.analyzer</code> class, and <code>data-theme</code> attribute to the document root.</p><h2 id="mode-rules" tabindex="-1">Mode Rules <a class="header-anchor" href="#mode-rules" aria-label="Permalink to &quot;Mode Rules&quot;">​</a></h2><p>Live mode permits light/dark and accent changes. Analyzer mode applies its dedicated analyzer theme and suppresses user theme/accent mutations until the app returns to live mode. Backend mode is synchronized from <code>/auth/analyzer-mode</code>; toggles use a CSRF token and <code>/auth/analyzer-toggle</code>.</p><p>Mode-change listeners allow data-heavy pages to refetch or reset state when moving between live and analyzer sources.</p><h2 id="css" tabindex="-1">CSS <a class="header-anchor" href="#css" aria-label="Permalink to &quot;CSS&quot;">​</a></h2><p><code>frontend/src/index.css</code> defines Tailwind variables, light/dark tokens, analyzer/sandbox overrides, and accent selectors. The frontend does not use DaisyUI or a separate Tailwind configuration file.</p><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><p>Theme and app-mode controls are rendered by <code>frontend/src/components/layout/Navbar.tsx</code>. Lucide icons and accessible labels describe light/dark actions. Accent choices set the store&#39;s <code>color</code> value rather than loading a separate stylesheet.</p><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to &quot;Invariants&quot;">​</a></h2><ul><li>Persist visual state across logout for continuity, but resynchronize trading app mode after authentication.</li><li>Never let a client-only color choice change backend analyzer/live behavior.</li><li>Analyzer/live toggle failures must leave the last confirmed app mode intact.</li><li>New accent names require both the TypeScript union and CSS variables/selectors.</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>frontend/src/stores/themeStore.ts</code></td><td>Persisted state and backend mode sync</td></tr><tr><td><code>frontend/src/components/layout/Navbar.tsx</code></td><td>User controls</td></tr><tr><td><code>frontend/src/index.css</code></td><td>Theme, accent, and mode variables</td></tr></tbody></table>',16)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
